import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as RadioGroup from "../../ui/shadcn-radio-group";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const optionView = (value: string, selected: boolean): Html => {
  const h = html<Message>();

  return h.div(
    [h.DataAttribute("invalid", ""), h.Class("flex items-center gap-3")],
    [
      h.button(
        [
          h.Type("button"),
          h.Role("radio"),
          h.AriaChecked(selected),
          h.AriaInvalid(true),
          h.AriaLabel(value),
        ],
        [selected ? RadioGroup.checkIcon() : RadioGroup.checkPlaceholder()]
      ),
      h.span([h.Class(RadioGroup.shadcnRadioGroupLabelClassName)], [value]),
    ]
  );
};

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-4")],
    [
      h.div(
        [h.Class(RadioGroup.shadcnRadioGroupMetaClassName)],
        [
          h.h3([h.Class("text-sm font-medium text-gray-950")], [
            "Notification Preferences",
          ]),
          h.p(
            [h.Class(RadioGroup.shadcnRadioGroupDescriptionClassName)],
            ["Choose how you want to receive notifications."]
          ),
        ]
      ),
      h.div(
        [
          h.Role("radiogroup"),
          h.AriaLabel("Notification Preferences"),
          h.Class(RadioGroup.shadcnRadioGroupVerticalClassName),
        ],
        [
          optionView("Email only", false),
          optionView("SMS only", false),
          optionView("Both Email & SMS", false),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("shadcn Radio Group Invalid example", () => {
  test("renders the origin invalid radio group demo", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("Notification Preferences")).toExist(),
      Scene.expect(
        Scene.text("Choose how you want to receive notifications.")
      ).toExist(),
      Scene.expect(Scene.role("radio", { name: "Email only" })).toHaveAttr(
        "aria-invalid",
        "true"
      ),
      Scene.expect(Scene.role("radio", { name: "Email only" })).not.toHaveHandler(
        "click"
      ),
      Scene.expect(Scene.role("radio", { name: "Both Email & SMS" })).toExist()
    );
  });
});
